const [lsr, raw] = await Promise.all([
  tools.pwsh({ command: "cd 'C:\\Users\\jjq21\\Desktop\\github\\dsh-our-free-model'; git ls-remote origin main 2>&1; echo '--- local HEAD ---'; git rev-parse HEAD; echo '--- cached origin/main ---'; git rev-parse origin/main", description: "Compare upstream main with local clone" }),
